package com.lighthome.tv;

import android.util.SparseArray;

/**
 * Maps remote-control keycodes to the package we want that button to launch
 * instead of the TV's own built-in handler.
 *
 * The mapping is entirely config-driven: AppConfig.REMOTE_KEYS is generated by
 * build.sh from the `remote_keys=` line in config.properties (format
 * "keycode:package,keycode:package,..."). The default is EMPTY, which means
 * RemoteKeys.isMapped() always returns false and RemoteKeyService /
 * RemoteKeyServiceGuard stay fully dormant -- no accessibility service is
 * ever enabled on a build that hasn't configured any keys.
 *
 * Specific TCL remote keycodes (observed on one TCL Google TV, Android 11 --
 * see docs/TCL-NOTES.md) are documented as a commented example in
 * config.example.properties. They are an example only; your remote and
 * firmware may use entirely different codes, which you'd need to capture
 * yourself (e.g. via `getevent`/logcat against the platform's key dispatcher).
 */
public final class RemoteKeys {

    private static final SparseArray<String> KEY_TO_PACKAGE = new SparseArray<>();

    static {
        for (java.util.Map.Entry<Integer, String> e : AppConfig.REMOTE_KEYS.entrySet()) {
            KEY_TO_PACKAGE.put(e.getKey(), e.getValue());
        }
    }

    public static boolean isMapped(int keyCode) {
        return KEY_TO_PACKAGE.get(keyCode) != null;
    }

    /** True only when at least one key is mapped -- governs whether the accessibility
     *  service guard is allowed to enable RemoteKeyService at all. */
    public static boolean hasAnyMapping() {
        return KEY_TO_PACKAGE.size() > 0;
    }

    public static String packageFor(int keyCode) {
        return KEY_TO_PACKAGE.get(keyCode);
    }

    public static String labelFor(int keyCode) {
        String pkg = KEY_TO_PACKAGE.get(keyCode);
        return pkg != null ? pkg : "App";
    }

    private RemoteKeys() {}
}
